import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import { saveAs } from 'file-saver';

// 全局防崩溃 Monkey Patch：拦截 html2canvas 解析渐变时的 NaN/Infinity 异常
if (typeof window !== 'undefined' && window.CanvasGradient) {
  const originalAddColorStop = CanvasGradient.prototype.addColorStop;
  CanvasGradient.prototype.addColorStop = function (offset: number, color: string) {
    if (!isFinite(offset) || isNaN(offset)) {
      offset = 0;
    }
    offset = Math.max(0, Math.min(1, offset));
    try {
      return originalAddColorStop.call(this, offset, color);
    } catch (e) {
      console.warn('CanvasGradient.addColorStop safe intercept:', e);
    }
  };
}

export interface ExportPdfOptions {
  /**
   * 需要导出的 DOM 节点，可以是单节点，也可以是多页节点数组（例如 .pages）
   */
  elements?: HTMLElement | HTMLElement[] | NodeListOf<HTMLElement> | null;
  /**
   * 导出的文件名（不带扩展名）
   */
  fileName?: string;
  /**
   * html2canvas 渲染倍率，默认为 2（高清），可选 3（超清）
   */
  scale?: number;
  /**
   * 单页简历标准高度（例如 1160px），用于长图切割分页
   */
  pageHeightPx?: number;
  /**
   * 进度回调函数
   */
  onProgress?: (percent: number, statusText: string) => void;
}

