/**
 * 校验 DOM 节点及其所有父节点是否为可视状态（排除 display:none / 隐藏弹窗内的节点）
 */
const isElementVisible = (el: HTMLElement): boolean => {
  if (!el) return false;
  if (el.offsetWidth === 0 && el.offsetHeight === 0) return false;

  let curr: HTMLElement | null = el;
  while (curr && curr !== document.body) {
    const style = window.getComputedStyle(curr);
    if (style.display === 'none' || style.visibility === 'hidden') {
      return false;
    }
    curr = curr.parentElement;
  }
  return true;
};

/**
 * 获取真正可见的待导出 DOM 列表（精确过滤隐藏弹窗/离屏渲染节点）
 */
const resolveElements = (
  target?: HTMLElement | HTMLElement[] | NodeListOf<HTMLElement> | null
): HTMLElement[] => {
  if (target) {
    const rawList = target instanceof HTMLElement ? [target] : Array.from(target);
    const visibleList = rawList.filter(isElementVisible);
    if (visibleList.length > 0) return visibleList;
    return rawList;
  }

  // 1. 优先获取积木搭建主画布中的可见 .pages 节点
  const mainPages = Array.from(
    document.querySelectorAll('.designer-box .pages, .designer .pages')
  ) as HTMLElement[];
  const visibleMainPages = mainPages.filter(isElementVisible);
  if (visibleMainPages.length > 0) {
    return visibleMainPages;
  }

  // 2. 获取全局任意可见的 .pages 节点
  const allPages = Array.from(document.querySelectorAll('.pages')) as HTMLElement[];
  const visibleAllPages = allPages.filter(isElementVisible);
  if (visibleAllPages.length > 0) {
    return visibleAllPages;
  }

  // 3. 查标准预览 DOM
  const designer = document.querySelector('.designer') || document.querySelector('.design');
  if (designer && isElementVisible(designer as HTMLElement)) {
    return [designer as HTMLElement];
  }

  return [];
};

/**
 * 纯前端高清 PDF 导出（支持多页 DOM 节点精确分页与长图自动切割）
 */
export const exportResumePdf = async (options: ExportPdfOptions = {}): Promise<boolean> => {
  const {
    elements,
    fileName = '我的简历',
    scale = 2,
    pageHeightPx = 1160,
    onProgress
  } = options;

  addExportStyles();

  const targetEls = resolveElements(elements);
  if (!targetEls || targetEls.length === 0) {
    throw new Error('未找到简历渲染节点，请确认页面已完全加载');
  }

  onProgress?.(5, '正在准备导出环境...');

  // A4 标准尺寸 (pt): 595.28 x 841.89
  const pdfWidth = 595.28;
  const pdfHeight = 841.89;
  const pdf = new jsPDF('p', 'pt', 'a4');

  // 给包含元素添加清洗类
  targetEls.forEach((el) => el.classList.add(CLEANUP_CLASS));

  try {
    // 情况 A：存在明确的多页 DOM 节点（如积木搭建器的多个 .pages）
    if (targetEls.length > 1) {
      const total = targetEls.length;
      for (let i = 0; i < total; i++) {
        const el = targetEls[i];
        onProgress?.(
          Math.round(10 + (i / total) * 75),
          `正在渲染第 ${i + 1} / ${total} 页...`
        );

        const canvas = await html2canvas(el, {
          scale,
          useCORS: true,
          allowTaint: true,
          logging: false,
          backgroundColor: '#ffffff'
        });

        const imgData = canvas.toDataURL('image/jpeg', 0.98);

        if (i > 0) {
          pdf.addPage();
        }

        pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
      }
    } else {
      // 情况 B：单个长 DOM 节点（如 1160px/2320px 高度的整体容器）
      const el = targetEls[0];
      // 如果 el 内部有多个 .pages 子节点，提取子节点作为多页处理
      const subPages = Array.from(el.querySelectorAll('.pages')).filter(
        (child) => isElementVisible(child as HTMLElement)
      );

      if (subPages.length > 1) {
        const total = subPages.length;
        for (let i = 0; i < total; i++) {
          const subEl = subPages[i] as HTMLElement;
          onProgress?.(
            Math.round(10 + (i / total) * 75),
            `正在渲染第 ${i + 1} / ${total} 页...`
          );

          const canvas = await html2canvas(subEl, {
            scale,
            useCORS: true,
            allowTaint: true,
            logging: false,
            backgroundColor: '#ffffff'
          });

          const imgData = canvas.toDataURL('image/jpeg', 0.98);
          if (i > 0) pdf.addPage();
          pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight);
        }
      } else {
        // 单个长 DOM，按 A4 比例进行 canvas 切片
        onProgress?.(20, '正在高保真捕捉画布...');
        const canvas = await html2canvas(el, {
          scale,
          useCORS: true,
          allowTaint: true,
          logging: false,
          backgroundColor: '#ffffff'
        });

        const contentWidth = canvas.width;
        const contentHeight = canvas.height;

        // 一页 A4 在 canvas 像素高度
        const pageCanvasHeight = contentWidth * (pdfHeight / pdfWidth);
        let leftHeight = contentHeight;
        let position = 0;
        let pageCount = 0;

        while (leftHeight > 0) {
          onProgress?.(
            Math.round(40 + (pageCount / Math.ceil(contentHeight / pageCanvasHeight)) * 45),
            `正在生成 PDF 第 ${pageCount + 1} 页...`
          );

          // 切片 canvas
          const sliceCanvas = document.createElement('canvas');
          sliceCanvas.width = contentWidth;
          sliceCanvas.height = Math.min(pageCanvasHeight, leftHeight);

          const ctx = sliceCanvas.getContext('2d');
          if (ctx) {
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, sliceCanvas.width, sliceCanvas.height);
            ctx.drawImage(
              canvas,
              0,
              position,
              contentWidth,
              sliceCanvas.height,
              0,
              0,
              contentWidth,
              sliceCanvas.height
            );
          }

          const sliceData = sliceCanvas.toDataURL('image/jpeg', 0.98);
          const slicePdfHeight = (sliceCanvas.height / contentWidth) * pdfWidth;

          if (pageCount > 0) pdf.addPage();
          pdf.addImage(sliceData, 'JPEG', 0, 0, pdfWidth, slicePdfHeight);

          leftHeight -= pageCanvasHeight;
          position += pageCanvasHeight;
          pageCount++;
        }
      }
    }

    onProgress?.(90, '正在合成 PDF 文件...');
    pdf.save(`${fileName}.pdf`);
    onProgress?.(100, '导出完成！');
    return true;
  } finally {
    targetEls.forEach((el) => el.classList.remove(CLEANUP_CLASS));
  }
};

/**
 * 矢量 PDF 系统打印（原生 window.print）
 */
export const exportResumePrint = (elements?: HTMLElement | HTMLElement[] | null) => {
  addExportStyles();

  // 直接在 Live DOM 开启打印模式，完美保留 Vue 作用域变量与各种 CSS 样式
  document.body.classList.add('is-printing-mode');

  const cleanup = () => {
    document.body.classList.remove('is-printing-mode');
  };

  window.addEventListener('afterprint', cleanup, { once: true });

  setTimeout(() => {
    window.print();
    // 兜底清除
    setTimeout(cleanup, 2000);
  }, 150);
};

/**
 * 高清图片 (PNG) 导出
 */
export const exportResumePNG = async (
  options: ExportPdfOptions = {}
): Promise<boolean> => {
  const { elements, fileName = '我的简历', scale = 2, onProgress } = options;
  addExportStyles();

  const targetEls = resolveElements(elements);
  if (!targetEls || targetEls.length === 0) {
    throw new Error('未找到简历渲染节点');
  }

  targetEls.forEach((el) => el.classList.add(CLEANUP_CLASS));

  try {
    const total = targetEls.length;
    for (let i = 0; i < total; i++) {
      onProgress?.(
        Math.round(((i + 1) / total) * 90),
        `正在渲染第 ${i + 1} / ${total} 页图片...`
      );
      const canvas = await html2canvas(targetEls[i], {
        scale,
        useCORS: true,
        allowTaint: true,
        logging: false,
        backgroundColor: '#ffffff'
      });

      await new Promise<void>((resolve) => {
        canvas.toBlob((blob) => {
          if (blob) {
            const pageSuffix = total > 1 ? `_第${i + 1}页` : '';
            saveAs(blob, `${fileName}${pageSuffix}.png`);
          }
          resolve();
        }, 'image/png');
      });
    }

    onProgress?.(100, '图片导出完成！');
    return true;
  } finally {
    targetEls.forEach((el) => el.classList.remove(CLEANUP_CLASS));
  }
};
