<template>
  <div class="template-select-box">
    <!-- 顶部存为模板按钮 -->
    <div class="top-action-bar">
      <el-button type="primary" class="save-btn" @click="openSaveDialog">
        <svg-icon icon-name="icon-jiahao" color="#fff" size="14px"></svg-icon>
        将当前画布存为模板
      </el-button>
    </div>

    <!-- 分类 Tab 切换 -->
    <div class="category-tabs">
      <div
        v-for="cate in categoryList"
        :key="cate"
        :class="['cate-item', { active: activeCate === cate }]"
        @click="switchCategory(cate)"
      >
        <span>{{ cate }}</span>
        <el-badge
          v-if="cate === '我的模板' && myTemplates.length > 0"
          :value="myTemplates.length"
          type="primary"
          class="cate-badge"
        />
      </div>
    </div>

    <!-- 模板卡片列表 -->
    <div class="template-list">
      <!-- 空状态 -->
      <div v-if="displayTemplates.length === 0" class="empty-box">
        <el-empty
          :description="activeCate === '我的模板' ? '暂无自定义模板，快点击顶部按钮保存吧！' : '暂无模板数据'"
          :image-size="80"
        />
      </div>

      <!-- 卡片组件 -->
      <div
        v-for="item in displayTemplates"
        :key="item.id || item._id"
        class="template-card-item"
      >
        <div
          class="card-cover-wrapper"
          @mouseenter="item.isHovered = true"
          @mouseleave="item.isHovered = false"
        >
          <img
            v-if="item.cover || item.previewUrl"
            :src="item.cover || item.previewUrl"
            alt="cover"
            class="cover-img"
            @error="handleImgError(item)"
          />
          <div v-else class="default-cover">
            <svg-icon icon-name="icon-zujian1" color="#94a3b8" size="32px"></svg-icon>
            <span class="default-cover-text">{{ item.title || item.name || '模板预览' }}</span>
          </div>

          <div :class="['cover-mask', { 'show-mask': item.isHovered }]">
            <div class="mask-action-box">
              <el-button
                type="danger"
                size="default"
                round
                class="mask-btn overwrite-btn"
                @click.stop="handleImportCommand(item, 'overwrite')"
              >
                🔴 覆盖当前画布
              </el-button>
              <el-button
                type="success"
                size="default"
                round
                class="mask-btn append-btn"
                @click.stop="handleImportCommand(item, 'append')"
              >
                🟢 追加到当前画布
              </el-button>
            </div>
          </div>
        </div>

        <div class="card-info">
          <div class="info-top">
            <span class="card-title" :title="item.title || item.name">{{ item.title || item.name }}</span>
            <el-tag v-if="item.isCustom" size="small" type="success" effect="plain">我的</el-tag>
            <el-tag v-else-if="item.category" size="small" type="info" effect="plain">{{ item.category }}</el-tag>
          </div>
          <div v-if="item.createTime" class="create-time">{{ item.createTime }}</div>
          <div v-else-if="item.description" class="card-desc">{{ item.description }}</div>

          <!-- 自定义模板操作栏 -->
          <div v-if="item.isCustom" class="card-actions">
            <el-button type="primary" link size="small" @click="refreshTemplateCover(item)">更新快照</el-button>
            <el-popconfirm
              title="确定删除此自定义模板吗？"
              confirm-button-text="确定"
              cancel-button-text="取消"
              @confirm="deleteCustomTemplate(item.id)"
            >
              <template #reference>
                <el-button type="danger" link size="small">删除</el-button>
              </template>
            </el-popconfirm>
          </div>
        </div>
      </div>
    </div>

    <!-- 存为模板弹窗 -->
    <save-template-dialog
      :dialog-visible="saveDialogVisible"
      @close="closeSaveDialog"
      @saved="onTemplateSaved"
    />
  </div>
</template>

<script lang="ts" setup>
  import { ref, computed, onMounted } from 'vue';
  import { ElMessage, ElMessageBox } from 'element-plus';
  import { ArrowDown } from '@element-plus/icons-vue';
  import { storeToRefs } from 'pinia';
  import appStore from '@/store';
  import { cloneDeep } from 'lodash';
  import { getUuid } from '@/utils/common';
  import SaveTemplateDialog from '../SaveTemplateDialog/SaveTemplateDialog.vue';
  import { getLegoTemplateListByCategoryAsync } from '@/http/api/lego';
  import { getImgBase64URL, renderFallbackCanvas } from '../../utils/html2img';

  const { HJSchemaJsonStore } = storeToRefs(appStore.useLegoJsonStore);
  const { changeHJSchemaJsonData } = appStore.useLegoJsonStore;
  const { setUuid } = appStore.useUuidStore;
  const { resetSelectWidget } = appStore.useLegoSelectWidgetStore;

  const saveDialogVisible = ref<boolean>(false);
  const activeCate = ref<string>('我的模板');

  const myTemplates = ref<any[]>([]);
  const systemTemplates = ref<any[]>([]);

  // 封面加载失败时的兜底处理
  const handleImgError = (item: any) => {
    const snap = renderFallbackCanvas();
    item.cover = snap;
    item.previewUrl = snap;
  };

  // 动态生成分类列表
  const categoryList = computed<string[]>(() => {
    const set = new Set<string>();
    set.add('我的模板');
    set.add('全部');
    myTemplates.value.forEach((item) => {
      if (item.category) set.add(item.category);
    });
    systemTemplates.value.forEach((item) => {
      if (item.category) set.add(item.category);
    });
    return Array.from(set);
  });

  // 加载我的自定义模板
  const loadMyTemplates = () => {
    const local = localStorage.getItem('LEGO_MY_TEMPLATES');
    if (local) {
      try {
        const list = JSON.parse(local);
        if (Array.isArray(list)) {
          myTemplates.value = list.map((item: any) => {
            if (!item.cover && !item.previewUrl) {
              const snap = renderFallbackCanvas();
              item.cover = snap;
              item.previewUrl = snap;
            }
            return item;
          });
        } else {
          myTemplates.value = [];
        }
      } catch (e) {
        myTemplates.value = [];
      }
    } else {
      myTemplates.value = [];
    }
  };

  // 加载系统在线/静态模板（只保留包含有效 JSON 数据的模板）
  const loadSystemTemplates = async () => {
    try {
      const res = await getLegoTemplateListByCategoryAsync({ page: 1, limit: 30 });
      if (res.status === 200 && res.data && res.data.list && res.data.list.length > 0) {
        const validList = res.data.list.filter(
          (item: any) => item.template_json || item.lego_json
        );
        if (validList.length > 0) {
          systemTemplates.value = validList;
          return;
        }
      }
    } catch (err) {
      console.warn('离线模式加载本地 templates.json...');
    }

    try {
      const resp = await fetch('/static/templates.json');
      if (resp.ok) {
        const rawList = await resp.json();
        systemTemplates.value = rawList.filter(
          (item: any) => item.template_json || item.lego_json
        );
      }
    } catch (e) {
      console.error('加载本地模板 JSON 失败', e);
    }
  };

  onMounted(() => {
    loadMyTemplates();
    loadSystemTemplates();
    window.addEventListener('LEGO_TEMPLATE_SAVED', () => {
      loadMyTemplates();
      activeCate.value = '我的模板';
    });
  });

  const switchCategory = (cate: string) => {
    activeCate.value = cate;
  };

  const displayTemplates = computed(() => {
    if (activeCate.value === '我的模板') {
      return myTemplates.value;
    }
    if (activeCate.value === '全部') {
      return [...myTemplates.value, ...systemTemplates.value];
    }
    const combined = [...myTemplates.value, ...systemTemplates.value];
    return combined.filter((item) => item.category === activeCate.value);
  });

  // 打开与关闭存为模板弹窗
  const openSaveDialog = () => {
    saveDialogVisible.value = true;
  };
  const closeSaveDialog = () => {
    saveDialogVisible.value = false;
  };
  const onTemplateSaved = () => {
    loadMyTemplates();
    activeCate.value = '我的模板';
  };

  // 删除自定义模板
  const deleteCustomTemplate = (id: string) => {
    myTemplates.value = myTemplates.value.filter((item) => item.id !== id);
    localStorage.setItem('LEGO_MY_TEMPLATES', JSON.stringify(myTemplates.value));
    ElMessage.success('已成功删除该自定义模板');
  };

  // 重新截取生成快照
  const refreshTemplateCover = async (item: any) => {
    try {
      const designerEl = document.querySelector('.pages') || document.querySelector('.designer');
      if (designerEl) {
        const snap = await getImgBase64URL(designerEl);
        if (snap) {
          item.cover = snap;
          item.previewUrl = snap;
          item.imgError = false;

          const local = localStorage.getItem('LEGO_MY_TEMPLATES');
          if (local) {
            let list = JSON.parse(local);
            const idx = list.findIndex((t: any) => t.id === item.id || t._id === item.id);
            if (idx !== -1) {
              list[idx].cover = snap;
              list[idx].previewUrl = snap;
              localStorage.setItem('LEGO_MY_TEMPLATES', JSON.stringify(list));
            }
          }
          ElMessage.success('🎉 已成功重新生成画布快照！');
        } else {
          ElMessage.warning('快照生成失败，请确认画布已正常渲染');
        }
      }
    } catch (e) {
      ElMessage.error('无法刷新快照');
    }
  };

  // 保证 Widget CSS 与 属性数据结构完整
  const ensureValidWidget = (w: any): any => {
    const css = w.css || {};
    const padding = css.padding || {};
    return {
      id: getUuid(),
      componentName: w.componentName || 'hj-text-1',
      commentType: w.commentType || 'text',
      category: w.category || 'text',
      icon: w.icon || '',
      title: w.title || '组件',
      description: w.description || '',
      props: w.props || {},
      customProps: w.customProps || {},
      css: {
        left: typeof css.left === 'number' ? css.left : (parseInt(css.left) || 40),
        top: typeof css.top === 'number' ? css.top : (parseInt(css.top) || 40),
        zIndex: typeof css.zIndex === 'number' ? css.zIndex : 1,
        width: typeof css.width === 'number' ? css.width : (parseInt(css.width) || 200),
        height: typeof css.height === 'number' ? css.height : (parseInt(css.height) || 40),
        rotate: typeof css.rotate === 'number' ? css.rotate : 0,
        fontSize: typeof css.fontSize === 'number' ? css.fontSize : 14,
        letterSpace: typeof css.letterSpace === 'number' ? css.letterSpace : 0,
        lineHeight: css.lineHeight || 1.5,
        fontFamily: css.fontFamily || '微软雅黑',
        fontWeight: css.fontWeight || 400,
        textAlign: css.textAlign || 'left',
        fontColor: css.fontColor || '#333333',
        backgroundColor: css.backgroundColor || '',
        padding: {
          top: typeof padding === 'object' && padding.top !== undefined ? Number(padding.top) : 0,
          right: typeof padding === 'object' && padding.right !== undefined ? Number(padding.right) : 0,
          bottom: typeof padding === 'object' && padding.bottom !== undefined ? Number(padding.bottom) : 0,
          left: typeof padding === 'object' && padding.left !== undefined ? Number(padding.left) : 0
        },
        borderWidth: typeof css.borderWidth === 'number' ? css.borderWidth : 0,
        borderRadius: typeof css.borderRadius === 'number' ? css.borderRadius : 0,
        borderColor: css.borderColor || '#eee',
        borderStyle: css.borderStyle || 'solid'
      },
      dataSource: w.dataSource || {}
    };
  };

  // 提取模板 JSON 结构
  const getExtractTemplateJson = (item: any): any => {
    let raw = item.template_json || item.lego_json || item;
    if (typeof raw === 'string') {
      try { raw = JSON.parse(raw); } catch(e){}
    }
    return cloneDeep(raw);
  };

  // 导入指令响应 (overwrite / append)
  const handleImportCommand = async (item: any, mode: string) => {
    let tplJson = getExtractTemplateJson(item);
    if (!tplJson || !tplJson.componentsTree) {
      // 尝试获取全量详情
      try {
        const fetchUrl = '/static/templates.json';
        const res = await fetch(fetchUrl);
        if (res.ok) {
          const list = await res.json();
          const found = list.find((t: any) => t.id == item.id || t._id == item._id || t.id == item._id);
          if (found && (found.template_json || found.lego_json)) {
            tplJson = cloneDeep(found.template_json || found.lego_json);
          }
        }
      } catch (err) {}
    }

    if (!tplJson || !tplJson.componentsTree) {
      ElMessage.warning('该模板结构解析异常或无可用 JSON 数据！');
      return;
    }

    try {
      if (mode === 'overwrite') {
        // 🔴 覆盖导入
        await ElMessageBox.confirm('覆盖当前画布将替换已有设计内容，是否确定？', '提示', {
          confirmButtonText: '确定覆盖',
          cancelButtonText: '取消',
          type: 'warning'
        });

        tplJson.id = getUuid();
        if (tplJson.config) {
          tplJson.config.title = item.title || item.name || '模板设计';
        }

        // 重新分配页面与组件 ID
        tplJson.componentsTree = tplJson.componentsTree.map((page: any) => ({
          ...page,
          id: getUuid(),
          children: (page.children || []).map((w: any) => ensureValidWidget(w))
        }));

        changeHJSchemaJsonData(tplJson);
        resetSelectWidget();
        setUuid();
        ElMessage.success(`🎉 已成功将模板【${item.title || item.name}】覆盖导入到画布！`);

      } else if (mode === 'append') {
        // 🟢 追加导入
        const newPages = tplJson.componentsTree.map((page: any) => ({
          id: getUuid(),
          componentName: 'page',
          commentType: 'page',
          oldPageIndex: '',
          children: (page.children || []).map((w: any) => ensureValidWidget(w))
        }));

        if (!HJSchemaJsonStore.value.componentsTree) {
          HJSchemaJsonStore.value.componentsTree = [];
        }

        HJSchemaJsonStore.value.componentsTree.push(...newPages);
        resetSelectWidget();
        setUuid();
        ElMessage.success(`🎉 已成功将模板【${item.title || item.name}】追加为新页面！`);
      }
    } catch (e: any) {
      if (e !== 'cancel') {
        console.error('导入模板出错:', e);
        ElMessage.error(e.message || '导入模板失败');
      }
    }
  };
</script>

