<template>
  <el-dialog
    :model-value="dialogPostWorkVisible"
    title="发布作品 / 存为模板"
    width="540px"
    append-to-body
    destroy-on-close
    class="post-work-dialog"
    @close="cancle"
  >
    <el-form
      ref="ruleFormRef"
      :model="ruleForm"
      :rules="rules"
      label-width="100px"
      size="default"
      label-position="left"
    >
      <el-form-item label="模板名称：" prop="title">
        <el-input v-model="ruleForm.title" placeholder="请输入模板标题/作品名称" maxlength="30" show-word-limit />
      </el-form-item>

      <el-form-item label="模板分类：" prop="category">
        <el-select
          v-model="ruleForm.category"
          filterable
          allow-create
          default-first-option
          placeholder="请选择或输入分类（如：前端开发、产品经理）"
          style="width: 100%"
        >
          <el-option
            v-for="(item, index) in categoryList"
            :key="index"
            :label="item.label"
            :value="item.label"
          />
        </el-select>
      </el-form-item>

      <el-form-item label="模板描述：">
        <el-input
          v-model="ruleForm.description"
          type="textarea"
          :rows="3"
          placeholder="请输入模板简要说明或适用岗位（选填）"
        />
      </el-form-item>
    </el-form>

    <template #footer>
      <span class="dialog-footer">
        <el-button @click="cancle">取消</el-button>
        <el-button type="primary" :loading="sureLoading" @click="submit(ruleFormRef)">
          {{ postWorkInfo ? '确认修改' : '确认保存' }}
        </el-button>
      </span>
    </template>
  </el-dialog>
</template>

<script lang="ts" setup>
  import { ref, reactive, watch, onMounted } from 'vue';
  import {
    getLegoCategoryListAsync,
    legoTemplateAddAsync,
    legoTemplateUpdateAsync
  } from '@/http/api/lego';
  import { FormInstance, FormRules, ElMessage } from 'element-plus';
  import appStore from '@/store';
  import { storeToRefs } from 'pinia';
  import { cloneDeep } from 'lodash';
  import { getUuid } from '@/utils/common';
  import { getImgBase64URL } from '../../utils/html2img';

  const { HJSchemaJsonStore } = storeToRefs(appStore.useLegoJsonStore);

  const emit = defineEmits(['cancle', 'updateSuccess']);
  interface TDialog {
    dialogPostWorkVisible: boolean;
    postWorkInfo: any;
  }
  const props = withDefaults(defineProps<TDialog>(), {
    dialogPostWorkVisible: false,
    postWorkInfo: null
  });

  interface ITemplate {
    title: string;
    category: string;
    previewUrl: string;
    description: string;
    how_much: number;
  }

  const ruleForm = reactive<ITemplate>({
    title: '',
    category: '个人自定义',
    previewUrl: '',
    description: '',
    how_much: 5
  });

  const rules = reactive<FormRules>({
    title: [{ required: true, message: '请输入模板标题', trigger: 'blur' }]
  });

  // 静默渲染捕捉画布快照作为封面预览图
  const autoGenerateSnapshot = async () => {
    try {
      const designerEl = document.querySelector('.pages') || document.querySelector('.designer');
      const snap = await getImgBase64URL(designerEl);
      if (snap) {
        ruleForm.previewUrl = snap;
      }
    } catch (e) {
      console.warn('捕获快照失败', e);
    }
  };

  watch(
    () => props.dialogPostWorkVisible,
    async (val) => {
      if (val) {
        getCategoryList();
        if (props.postWorkInfo) {
          ruleForm.title = props.postWorkInfo.title || '';
          ruleForm.category = props.postWorkInfo.category || '个人自定义';
          ruleForm.previewUrl = props.postWorkInfo.previewUrl || props.postWorkInfo.cover || '';
          ruleForm.description = props.postWorkInfo.description || '';
        } else {
          ruleForm.title = HJSchemaJsonStore.value?.config?.title || '我的作品模板';
          ruleForm.category = categoryList.value[0]?.label || '个人自定义';
          ruleForm.description = '';
          ruleForm.previewUrl = '';
        }
      }
    }
  );

  const cancle = () => {
    emit('cancle');
  };

  // 查询分类列表（结合 API 与 本地已存分类）
  const categoryList = ref<any[]>([]);
  const getCategoryList = async () => {
    const set = new Set<string>(['个人自定义', '前端开发', '产品经理']);
    
    // 收集本地已存分类
    const local = localStorage.getItem('LEGO_MY_TEMPLATES');
    if (local) {
      try {
        const list = JSON.parse(local);
        list.forEach((item: any) => {
          if (item.category) set.add(item.category);
        });
      } catch (e) {}
    }

    try {
      const data = await getLegoCategoryListAsync();
      if (data.data && data.data.status && data.data.data) {
        data.data.data.forEach((item: { name: string }) => {
          if (item.name) set.add(item.name);
        });
      }
    } catch (e) {}

    categoryList.value = Array.from(set).map((cat) => ({
      label: cat,
      value: cat
    }));
  };

  onMounted(() => {
    getCategoryList();
  });

  // 提交：保存至 localStorage 个人模板并同步提交 API
  const sureLoading = ref<boolean>(false);
  const ruleFormRef = ref<any>(null);
  const submit = async (formEl: FormInstance | undefined) => {
    if (!formEl) return;
    await formEl.validate(async (valid) => {
      if (!valid) return;
      try {
        sureLoading.value = true;
        
        // 自动静默截取当前画布快照作为预览图
        if (!ruleForm.previewUrl) {
          await autoGenerateSnapshot();
        }

        const jsonCopy = cloneDeep(HJSchemaJsonStore.value);
        if (jsonCopy.config) {
          jsonCopy.config.title = ruleForm.title;
        }

        const newTemplate = {
          id: getUuid(),
          _id: props.postWorkInfo?._id || getUuid(),
          name: ruleForm.title,
          title: ruleForm.title,
          template_title: ruleForm.title,
          category: ruleForm.category || '个人自定义',
          description: ruleForm.description || '',
          cover: ruleForm.previewUrl,
          previewUrl: ruleForm.previewUrl,
          isCustom: true,
          createTime: new Date().toLocaleString(),
          template_json: jsonCopy
        };

        // 本地模板持久化存储
        const localData = localStorage.getItem('LEGO_MY_TEMPLATES');
        let myTemplates: any[] = [];
        if (localData) {
          try {
            myTemplates = JSON.parse(localData);
          } catch (e) {
            myTemplates = [];
          }
        }

        // 如果是更新，则替换，否则插在最前面
        const existingIdx = myTemplates.findIndex((t) => t.id === newTemplate.id || t._id === newTemplate._id);
        if (existingIdx !== -1) {
          myTemplates[existingIdx] = newTemplate;
        } else {
          myTemplates.unshift(newTemplate);
        }
        localStorage.setItem('LEGO_MY_TEMPLATES', JSON.stringify(myTemplates));
        window.dispatchEvent(new CustomEvent('LEGO_TEMPLATE_SAVED', { detail: newTemplate }));

        // 同步提交服务端（静默捕获异常）
        try {
          let params = {
            lego_json: jsonCopy,
            previewUrl: ruleForm.previewUrl,
            category: ruleForm.category,
            how_much: ruleForm.how_much,
            title: ruleForm.title
          };
          if (!props.postWorkInfo) {
            await legoTemplateAddAsync(params);
          } else {
            await legoTemplateUpdateAsync({ ...params, _id: props.postWorkInfo._id });
          }
        } catch (e) {
          console.warn('服务端同步受限，已存为本地模板');
        }

        ElMessage.success('🎉 成功保存模板！可在【模板 -> 我的模板】中随时使用。');
        emit('updateSuccess', newTemplate);
        cancle();
      } catch (err: any) {
        ElMessage.error(err.message || '发布失败');
      } finally {
        sureLoading.value = false;
      }
    });
  };
</script>

<style lang="scss" scoped>
  .post-work-dialog {
    .dialog-footer button:first-child {
      margin-right: 10px;
    }
  }
</style>
