<template>
  <div class="lego-nav-box">
    <div class="nav-left">
      <logo-com icon-color="#74a274" font-color="#74a274"></logo-com>
      <div class="nav-menu">
        <span :class="['menu-item', { active: route.path === '/legoDesigner' }]" @click="router.push('/legoDesigner')">积木搭建器</span>
        <span :class="['menu-item', { active: route.path === '/imgCompress' }]" @click="router.push('/imgCompress')">图片压缩</span>
      </div>
    </div>
    <div class="nav-right">
      <el-tooltip effect="dark" content="预览简历" placement="bottom">
        <div class="icon-box" @click="previewResume">
          <svg-icon icon-name="icon-yulan1" color="#555" size="18px"></svg-icon>
          <span class="icon-tips">预览</span>
        </div>
      </el-tooltip>
      <el-tooltip effect="dark" content="保存为草稿" placement="bottom">
        <div class="icon-box" @click="saveDraft">
          <svg-icon icon-name="icon-caogaoxiang1" color="#555" size="16px"></svg-icon>
          <span class="icon-tips">保存</span>
        </div>
      </el-tooltip>
      <el-tooltip effect="dark" content="重置所有设置" placement="bottom">
        <div class="icon-box" @click="reset">
          <svg-icon icon-name="icon-zhongzhi" color="#555" size="16px"></svg-icon>
          <span class="icon-tips">重置</span>
        </div>
      </el-tooltip>
      <el-tooltip effect="dark" content="导入JSON配置并快速搭建" placement="bottom">
        <div class="icon-box" @click="openImportJsonDialog">
          <svg-icon icon-name="icon-xiazai" color="#555" size="16px"></svg-icon>
          <span class="icon-tips">导入JSON</span>
        </div>
      </el-tooltip>
      <el-tooltip effect="dark" content="导出 PDF、图片或 JSON 配置" placement="bottom">
        <div class="icon-box icon-export-pdf" @click="openDownloadDialog">
          <svg-icon icon-name="icon-pdf" color="#fff" size="18px"></svg-icon>
          <span class="icon-tips">导出</span>
        </div>
      </el-tooltip>
      <el-tooltip
        v-if="templateId && templateInfo"
        effect="dark"
        content="快来一起参与评论吧！"
        placement="bottom"
      >
        <div class="icon-box" @click="publishComment">
          <svg-icon icon-name="icon-pinglun" color="#555" size="17px"></svg-icon>
          <span class="icon-tips">评论({{ templateInfo.commentCount }})</span>
        </div>
      </el-tooltip>
      <el-tooltip
        v-if="!templateId"
        effect="dark"
        content="存为自定义模板，方便随时重复使用"
        placement="bottom"
      >
        <div class="icon-box icon-download" @click="publishTemplate">
          <svg-icon icon-name="icon-fabu1" color="#fff" size="16px"></svg-icon>
          <span class="icon-tips">{{ postWorkInfo ? '更新模板' : '保存模板' }}</span>
        </div>
      </el-tooltip>
    </div>
  </div>

  <!-- 下载/导出 PDF 弹窗 -->
  <download-dialog
    :dialog-download-visible="dialogDownloadVisible"
    @close-download-dialog="closeDownloadDialog"
  ></download-dialog>

  <!-- 导入 JSON 弹窗 -->
  <lego-import-json-dialog
    :dialog-visible="dialogImportJsonVisible"
    @close="closeImportJsonDialog"
  ></lego-import-json-dialog>

  <!-- 存为自定义模板弹窗 -->
  <save-template-dialog
    :dialog-visible="dialogSaveTemplateVisible"
    @close="closeSaveTemplateDialog"
  ></save-template-dialog>

  <!-- 预览 -->
  <preview-image v-if="dialogPreviewVisible" @close="closePreview">
    <render-page></render-page>
  </preview-image>

  <!-- 发布作品弹窗 -->
  <post-work-dialog
    :dialog-post-work-visible="dialogPostWorkVisible"
    :post-work-info="postWorkInfo"
    @cancle="canclePostWork"
    @update-success="handlePostWorkSuccess"
  ></post-work-dialog>

  <!-- 评论抽屉 -->
  <el-drawer
    v-model="commentDrawer"
    append-to-body
    class="lego-comment-box"
    modal-class="lego-comment-box-modal"
    :show-close="false"
    direction="rtl"
  >
    <comment-com
      v-config:open_comment
      :comment-type-id="templateId"
      comment-type="legoTemplate"
      width="100%"
    ></comment-com>
  </el-drawer>
</template>
<script lang="ts" setup>
  import appStore from '@/store';
  import { ElMessageBox } from 'element-plus';
  import { nextTick, ref } from 'vue';
  import FileSaver from 'file-saver';
  import { cloneDeep } from 'lodash';
  import { storeToRefs } from 'pinia';
  import PreviewImage from '../render/PreviewImage/PreviewImage.vue';
  import RenderPage from '../render/index.vue';
  import { CONFIG } from '../config/lego';
  import moment from 'moment';
  import { getImgBase64URL } from '../utils/html2img';
  import { legoUserResumeAsync } from '@/http/api/lego';
  import PostWorkDialog from './PostWorkDialog/PostWorkDialog.vue';
  import DownloadDialog from './DownloadDialog/DownloadDialog.vue';
  import { useRoute, useRouter, onBeforeRouteLeave } from 'vue-router';
  import { getIntegralPayNumber } from '../utils/common';

  import LegoImportJsonDialog from './ImportJsonDialog/LegoImportJsonDialog.vue';
  import SaveTemplateDialog from './SaveTemplateDialog/SaveTemplateDialog.vue';

  const route = useRoute();
  const router = useRouter();

  const { HJSchemaJsonStore, draftTips } = storeToRefs(appStore.useLegoJsonStore);
  const { resetHJSchemaJsonData } = appStore.useLegoJsonStore;
  const { setUuid } = appStore.useRefreshStore;
  const { resetSelectWidget } = appStore.useLegoSelectWidgetStore;

  // 导出 PDF / 下载简历 弹窗控制
  const dialogDownloadVisible = ref<boolean>(false);
  const openDownloadDialog = () => {
    dialogDownloadVisible.value = true;
  };
  const closeDownloadDialog = () => {
    dialogDownloadVisible.value = false;
  };

  // 存为模板/发布作品 弹窗控制
  const openSaveTemplateDialog = () => {
    dialogPostWorkVisible.value = true;
  };
  const closeSaveTemplateDialog = () => {
    dialogPostWorkVisible.value = false;
  };

  // 导入 JSON 弹窗控制
  const dialogImportJsonVisible = ref<boolean>(false);
  const openImportJsonDialog = () => {
    dialogImportJsonVisible.value = true;
  };
  const closeImportJsonDialog = () => {
    dialogImportJsonVisible.value = false;
  };
  const { templateId, category } = useRoute().query;

  const props = defineProps<{
    pagesRefs: any;
    postWorkInfo: any;
    templateInfo: any;
  }>();

  // 查询导出为pdf需要的简币数
  const exportPdfPayIntegral = ref<number>(0);
  // 查询导出为图片需要的简币数
  const exportImgPayIntegral = ref<number>(0);
  onMounted(async () => {
    exportImgPayIntegral.value = Number(await getIntegralPayNumber('6'));
    exportPdfPayIntegral.value = Number(await getIntegralPayNumber('5'));
  });

  // 导出JSON
  const exportJSON = () => {
    let JSONData = cloneDeep(HJSchemaJsonStore.value);
    const data = JSON.stringify(JSONData, null, 4);
    const blob = new Blob([data], { type: '' });
    FileSaver.saveAs(blob, HJSchemaJsonStore.value.config.title + '.json');
  };

  // 预览
  const dialogPreviewVisible = ref<boolean>(false);
  const previewResume = () => {
    dialogPreviewVisible.value = true;
  };

  // 关闭预览弹窗
  const closePreview = () => {
    dialogPreviewVisible.value = false;
  };

  // 发布作品（集成存为模板功能）
  const dialogPostWorkVisible = ref<boolean>(false);
  const publishTemplate = () => {
    dialogPostWorkVisible.value = true;
  };

  // 取消发布弹窗
  const canclePostWork = () => {
    dialogPostWorkVisible.value = false;
  };

  // 发布或更新作品成功
  const handlePostWorkSuccess = async () => {
    dialogPostWorkVisible.value = false;
  };

  // 优化后的草稿极速保存机制（<10ms毫秒级保存）
  const imgUrl = ref<string>('');
  const _id = ref<string>('');
  const saveDraft = async () => {
    try {
      // 1. 本地极速保存（不卡顿、秒级落盘）
      const currentId = HJSchemaJsonStore.value.id || 'default_lego_id';
      let LegoLocal = localStorage.getItem('LegoLogo');
      let temp: { [propName: string]: any } = {};
      if (LegoLocal) {
        try {
          temp = JSON.parse(LegoLocal);
        } catch (e) {
          temp = {};
        }
      }
      temp[currentId] = cloneDeep(HJSchemaJsonStore.value);
      localStorage.setItem('LegoLogo', JSON.stringify(temp));

      const time = moment(new Date()).format('YYYY.MM.DD HH:mm:ss');
      draftTips.value = `已保存草稿  ${time}`;
      ElMessage.success('草稿保存成功');

      // 2. 异步后台离屏静默同步快照与服务端（不阻塞用户UI）
      setTimeout(async () => {
        try {
          if (props.pagesRefs && props.pagesRefs[0]) {
            const snap = await getImgBase64URL(props.pagesRefs[0]);
            if (snap) imgUrl.value = snap;
          }
          const params = {
            previewUrl: imgUrl.value || '',
            category: category || '个人自定义',
            lego_json: HJSchemaJsonStore.value
          };
          const data = await legoUserResumeAsync(params);
          if (data.data?.status === 200 && data.data?.data?._id) {
            _id.value = data.data.data._id;
          }
        } catch (e) {
          console.warn('静默后台草稿同步完成');
        }
      }, 50);
    } catch (err: any) {
      ElMessage.error('草稿保存失败');
    }
  };

  // 重置
  const reset = () => {
    ElMessageBox.confirm('此操作会重置画布至初始状态，是否继续?', '警告', {
      confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning'
    })
      .then(() => {
        // 重置JSON
        const id = HJSchemaJsonStore.value.id;
        resetHJSchemaJsonData(id);
        console.log('HJSchemaJsonStore', HJSchemaJsonStore);
        // 重置选中状态
        resetSelectWidget();
        setUuid();
      })
      .catch(() => {});
  };

  // 发布公开简历
  const publishOnlineResume = () => {};

  // 离开页面之前
  onBeforeUnmount(async () => {
    draftTips.value = '';
    // 重置JSON
    resetHJSchemaJsonData();
    // 重置选中状态
    resetSelectWidget();
    setUuid();
  });

  // 打开评论弹窗
  const commentDrawer = ref<boolean>(false);
  const publishComment = () => {
    commentDrawer.value = true;
  };

  // 监听路由离开
  onBeforeRouteLeave((to, from, next) => {
    if (to.path === '/postWorkSuccess') {
      next();
      return true;
    }
    // 编辑状态离开时
    ElMessageBox.confirm('离开前请确保您编辑的内容已保存草稿！', '警告', {
      confirmButtonText: '保存草稿并离开',
      cancelButtonText: '直接离开',
      showCancelButton: true,
      closeOnClickModal: false,
      closeOnPressEscape: false,
      distinguishCancelAndClose: true,
      type: 'warning',
      beforeClose: async (action, instance, done) => {
        if (action === 'confirm') {
          instance.confirmButtonLoading = true;
          // 保存草稿并离开
          await saveDraft();
          instance.confirmButtonLoading = false;
          done();
        } else if (action === 'close') {
          done();
          return;
        } else {
          done();
          next();
        }
      }
    })
      .then(async () => {
        next();
      })
      .catch(() => {});
  });
</script>
