import html2canvas from 'html2canvas';
import appStore from '@/store';

/**
 * 渲染 2D 兜底画布快照 (保证 100% 产生有效 Base64 图片，防卡片图片加载失败)
 */
export const renderFallbackCanvas = (): string => {
  try {
    const store = appStore.useLegoJsonStore;
    const schema = store?.HJSchemaJsonStore?.value || store?.HJSchemaJsonStore;

    const canvas = document.createElement('canvas');
    const width = 820;
    const height = 1160;
    canvas.width = Math.round(width * 0.35);
    canvas.height = Math.round(height * 0.35);
    const ctx = canvas.getContext('2d');
    if (!ctx) return '';

    ctx.scale(0.35, 0.35);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    if (schema) {
      const firstPage = schema.componentsTree?.[0];
      if (firstPage && Array.isArray(firstPage.children)) {
        firstPage.children.forEach((w: any) => {
          const css = w.css || {};
          const left = Number(css.left) || 0;
          const top = Number(css.top) || 0;
          const wWidth = Number(css.width) || 200;
          const wHeight = Number(css.height) || 40;

          if (css.backgroundColor) {
            ctx.fillStyle = css.backgroundColor;
            ctx.fillRect(left, top, wWidth, wHeight);
          }

          const text = w.dataSource?.text || w.title || '';
          if (text) {
            ctx.fillStyle = css.fontColor || '#333333';
            ctx.font = `${css.fontWeight || 400} ${css.fontSize || 14}px "微软雅黑", sans-serif`;
            ctx.textBaseline = 'top';
            ctx.fillText(String(text).substring(0, 30), left + 4, top + 4);
          }

          if (w.isAvatar || w.componentName?.includes('avatar')) {
            ctx.fillStyle = '#e2e8f0';
            ctx.fillRect(left, top, wWidth, wHeight);
            ctx.fillStyle = '#94a3b8';
            ctx.font = '12px "微软雅黑", sans-serif';
            ctx.fillText('照片', left + wWidth / 2 - 12, top + wHeight / 2 - 6);
          }
        });
      }
    }
    return canvas.toDataURL('image/jpeg', 0.8);
  } catch (e) {
    console.warn('renderFallbackCanvas 渲染异常:', e);
    const c = document.createElement('canvas');
    c.width = 200;
    c.height = 280;
    const context = c.getContext('2d');
    if (context) {
      context.fillStyle = '#ffffff';
      context.fillRect(0, 0, 200, 280);
      context.fillStyle = '#64748b';
      context.font = '14px sans-serif';
      context.fillText('简历模板', 70, 140);
    }
    return c.toDataURL('image/jpeg', 0.8);
  }
};

/**
 * 抓取当前画布 DOM 节点并生成高清 Base64 预览图
 */
export const getImgBase64URL = async (targetEl?: any): Promise<string> => {
  const el = targetEl || document.querySelector('.designer-box .pages') || document.querySelector('.pages');
  if (!el) {
    return renderFallbackCanvas();
  }

  try {
    const canvas = await html2canvas(el as HTMLElement, {
      scale: 0.35,
      useCORS: true,
      allowTaint: true,
      logging: false,
      backgroundColor: '#ffffff',
      ignoreElements: (element) => {
        return (
          element.classList?.contains('v-contextmenu') ||
          element.classList?.contains('handle') ||
          element.classList?.contains('vdr-line') ||
          element.classList?.contains('lines') ||
          element.classList?.contains('vdr-sticky-container')
        );
      }
    });

    const dataURL = canvas.toDataURL('image/jpeg', 0.85);
    if (dataURL && dataURL.length > 200) {
      return dataURL;
    }
    return renderFallbackCanvas();
  } catch (err) {
    console.warn('html2canvas 画布截取异常，使用 2D 兜底画布:', err);
    return renderFallbackCanvas();
  }
};
