<template>
  <el-dialog
    :model-value="dialogVisible"
    width="500px"
    title="发布作品 / 存为模板"
    append-to-body
    destroy-on-close
    class="save-template-dialog"
    @close="handleClose"
  >
    <el-form ref="formRef" :model="form" :rules="rules" label-width="90px">
      <el-form-item label="模板名称" prop="title">
        <el-input v-model="form.title" placeholder="请输入模板名称" maxlength="30" show-word-limit />
      </el-form-item>
      <el-form-item label="模板分类">
        <el-select
          v-model="form.category"
          filterable
          allow-create
          default-first-option
          placeholder="请输入或选择分类（如：前端开发、产品经理）"
          style="width: 100%"
        >
          <el-option
            v-for="cat in existingCategories"
            :key="cat"
            :label="cat"
            :value="cat"
          />
        </el-select>
      </el-form-item>
      <el-form-item label="模板描述">
        <el-input
          v-model="form.description"
          type="textarea"
          :rows="3"
          placeholder="请输入模板简要说明或适用岗位（选填）"
        />
      </el-form-item>
    </el-form>

    <template #footer>
      <div class="dialog-footer">
        <el-button @click="handleClose">取消</el-button>
        <el-button type="primary" :loading="saving" @click="handleSave">确认保存</el-button>
      </div>
    </template>
  </el-dialog>
</template>

<script lang="ts" setup>
  import { ref, reactive, watch, computed } from 'vue';
  import { ElMessage } from 'element-plus';
  import appStore from '@/store';
  import { storeToRefs } from 'pinia';
  import { cloneDeep } from 'lodash';
  import { getUuid } from '@/utils/common';
  import { getImgBase64URL } from '../../utils/html2img';

  const props = defineProps<{
    dialogVisible: boolean;
  }>();

  const emit = defineEmits(['close', 'saved']);

  const { HJSchemaJsonStore } = storeToRefs(appStore.useLegoJsonStore);

  const saving = ref<boolean>(false);
  const formRef = ref<any>(null);

  const form = reactive({
    title: '',
    category: '个人自定义',
    description: ''
  });

  const existingCategories = ref<string[]>(['个人自定义']);

  const loadCategories = () => {
    const set = new Set<string>(['个人自定义']);
    const localData = localStorage.getItem('LEGO_MY_TEMPLATES');
    if (localData) {
      try {
        const list = JSON.parse(localData);
        list.forEach((item: any) => {
          if (item.category) set.add(item.category);
        });
      } catch (e) {}
    }
    existingCategories.value = Array.from(set);
  };

  const rules = {
    title: [{ required: true, message: '请输入模板名称', trigger: 'blur' }]
  };

  watch(
    () => props.dialogVisible,
    (val) => {
      if (val) {
        loadCategories();
        form.title = HJSchemaJsonStore.value?.config?.title || '我的自定义模板';
        form.category = existingCategories.value[0] || '个人自定义';
        form.description = '';
      }
    }
  );

  const handleClose = () => {
    emit('close');
  };

  const handleSave = async () => {
    if (!formRef.value) return;
    await formRef.value.validate(async (valid: boolean) => {
      if (!valid) return;
      try {
        saving.value = true;
        let coverUrl = '';
        try {
          const designerEl = document.querySelector('.designer') || document.querySelector('.pages');
          if (designerEl) {
            coverUrl = await getImgBase64URL(designerEl);
          }
        } catch (e) {
          console.warn('捕获画布快照失败', e);
        }

        const jsonCopy = cloneDeep(HJSchemaJsonStore.value);
        if (jsonCopy.config) {
          jsonCopy.config.title = form.title;
        }

        const newTemplate = {
          id: getUuid(),
          _id: getUuid(),
          name: form.title,
          title: form.title,
          template_title: form.title,
          category: form.category || '个人自定义',
          description: form.description || '',
          cover: coverUrl,
          previewUrl: coverUrl,
          isCustom: true,
          createTime: new Date().toLocaleString(),
          template_json: jsonCopy
        };

        const localData = localStorage.getItem('LEGO_MY_TEMPLATES');
        let myTemplates: any[] = [];
        if (localData) {
          try {
            myTemplates = JSON.parse(localData);
          } catch (e) {
            myTemplates = [];
          }
        }

        myTemplates.unshift(newTemplate);
        localStorage.setItem('LEGO_MY_TEMPLATES', JSON.stringify(myTemplates));

        ElMessage.success('🎉 成功发布为模板作品！您可在【模板 -> 我的模板】中随时使用。');
        emit('saved', newTemplate);
        handleClose();
      } catch (err: any) {
        ElMessage.error(err.message || '保存失败');
      } finally {
        saving.value = false;
      }
    });
  };
</script>

<style lang="scss" scoped>
  .save-template-dialog {
    .dialog-footer {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
    }
  }
</style>
