<template>
  <div class="avatar-editor">
    <el-form-item label="图片上传:">
      <el-upload
        class="hj-img-uploader"
        action="#"
        :http-request="customImgUpload"
        :show-file-list="false"
        accept=".jpg,.jpeg,.png,.gif,.JPG,.JPEG,.PNG,.GIF"
      >
        <img
          v-if="widgetItem?.dataSource?.imgUrl"
          :src="getImgListStyleImageFile(widgetItem.dataSource.imgUrl)"
          class="avatar"
        />
        <el-icon v-else class="avatar-uploader-icon"><Plus /></el-icon>
      </el-upload>
      <p class="tips">图片大小不能超过 5M，支持本地实时更换（jpg, jpeg, png, gif）</p>
    </el-form-item>
  </div>
</template>
<script lang="ts" setup>
  import { ElMessage } from 'element-plus';
  import useSelectWidgetItem from '../../hooks/useSelectWidgetItem';
  import { getImgListStyleImageFile } from '../../widgets/image/imageList';

  const props = defineProps<{
    id: string;
    pageIndex: number;
  }>();

  // 选中的 widgetItem
  const { widgetItem } = useSelectWidgetItem(props.id, props.pageIndex);

  // 自定义文件上传：利用 FileReader 本地秒级转换
  const customImgUpload = (options: any) => {
    const file = options.file;
    if (!file) return;

    if (file.size / 1024 / 1024 > 5) {
      ElMessage.error('图片大小不能超过 5M');
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      if (e.target?.result && widgetItem) {
        widgetItem.dataSource.imgUrl = e.target.result as string;
        ElMessage.success('图片上传成功！');
      }
    };
    reader.readAsDataURL(file);
  };
</script>
