<!-- 简历导出与下载弹窗 -->
<template>
  <el-dialog
    class="download-resume-dialog"
    :model-value="dialogDownloadVisible"
    title="导出与下载简历"
    width="560px"
    append-to-body
    :close-on-click-modal="!isExporting"
    @close="handleClose"
  >
    <div class="content-box">
      <!-- 导出未开始状态：模式选择 -->
      <template v-if="!isExporting">
        <div class="export-options-grid">
          <!-- 1. 高清 PDF 导出 -->
          <div class="option-card pdf-hd-card" @click="handleExport('pdf-hd')">
            <div class="card-icon-wrapper pdf-icon">
              <svg-icon icon-name="icon-pdf" color="#fff" size="30px"></svg-icon>
            </div>
            <div class="card-body">
              <div class="card-title">
                <span>高清 PDF 导出</span>
                <span class="recommend-tag">推荐</span>
              </div>
              <p class="card-desc">纯前端离线生成，多页高清防截断</p>
            </div>
            <div class="card-action">
              <el-button type="primary" size="small" round>导出 PDF</el-button>
            </div>
          </div>

          <!-- 2. 矢量打印 PDF 导出 -->
          <div class="option-card print-card" @click="handleExport('pdf-print')">
            <div class="card-icon-wrapper print-icon">
              <svg-icon icon-name="icon-dayin" color="#fff" size="28px"></svg-icon>
            </div>
            <div class="card-body">
              <div class="card-title">
                <span>矢量 PDF 打印</span>
              </div>
              <p class="card-desc">唤起浏览器原生打印，文字可选中</p>
            </div>
            <div class="card-action">
              <el-button type="success" size="small" round plain>系统打印</el-button>
            </div>
          </div>

          <!-- 3. 高清图片导出 -->
          <div class="option-card img-card" @click="handleExport('png')">
            <div class="card-icon-wrapper img-icon">
              <svg-icon icon-name="icon-tupian" color="#fff" size="28px"></svg-icon>
            </div>
            <div class="card-body">
              <div class="card-title">
                <span>高清图片 (PNG)</span>
              </div>
              <p class="card-desc">全分辨率图片保存，适合微信分享</p>
            </div>
            <div class="card-action">
              <el-button type="info" size="small" round plain>导出 PNG</el-button>
            </div>
          </div>

          <!-- 4. JSON 配置文件导出 -->
          <div class="option-card json-card" @click="handleExport('json')">
            <div class="card-icon-wrapper json-icon">
              <svg-icon icon-name="icon-xiazai" color="#fff" size="26px"></svg-icon>
            </div>
            <div class="card-body">
              <div class="card-title">
                <span>JSON 配置文件</span>
              </div>
              <p class="card-desc">导出完整数据结构，支持二次导入编辑</p>
            </div>
            <div class="card-action">
              <el-button type="warning" size="small" round plain>导出 JSON</el-button>
            </div>
          </div>
        </div>
      </template>

      <!-- 导出进行中/完成状态：进度条 -->
      <template v-else>
        <div class="export-progress-box">
          <div class="progress-header">
            <div class="progress-title">{{ statusText }}</div>
            <div class="progress-num">{{ progressPercent }}%</div>
          </div>
          <el-progress
            :percentage="progressPercent"
            :status="progressPercent === 100 ? 'success' : ''"
            :stroke-width="12"
            striped
            striped-flow
          />
          <p class="progress-tips">请稍等，正在为您精心合成最高画质的文件...</p>
        </div>
      </template>
    </div>
  </el-dialog>
</template>

<script lang="ts" setup>
  import { ref } from 'vue';
  import appStore from '@/store';
  import { storeToRefs } from 'pinia';
  import { exportResumePdf, exportResumePrint, exportResumePNG } from '@/utils/pdfExport';
  import { ElMessage } from 'element-plus';
  import { cloneDeep } from 'lodash';
  import FileSaver from 'file-saver';

  const emit = defineEmits(['closeDownloadDialog', 'downloadFile']);

  interface TDialog {
    dialogDownloadVisible: boolean;
    exportPdfPayIntegral?: number;
    exportImgPayIntegral?: number;
  }
  withDefaults(defineProps<TDialog>(), {
    dialogDownloadVisible: false,
    exportPdfPayIntegral: 0,
    exportImgPayIntegral: 0
  });

  const isExporting = ref<boolean>(false);
  const progressPercent = ref<number>(0);
  const statusText = ref<string>('正在准备导出...');

  const getFileName = () => {
    try {
      const { HJSchemaJsonStore } = storeToRefs(appStore.useLegoJsonStore);
      if (HJSchemaJsonStore.value?.config?.title) {
        return HJSchemaJsonStore.value.config.title;
      }
    } catch (e) {}

    try {
      const { resumeJsonNewStore } = storeToRefs(appStore.useResumeJsonNewStore);
      if (resumeJsonNewStore.value?.TITLE) {
        return resumeJsonNewStore.value.TITLE;
      }
    } catch (e) {}

    return '我的简历';
  };

  const exportJsonConfig = () => {
    try {
      const { HJSchemaJsonStore } = storeToRefs(appStore.useLegoJsonStore);
      if (HJSchemaJsonStore?.value && HJSchemaJsonStore.value.componentsTree) {
        const JSONData = cloneDeep(HJSchemaJsonStore.value);
        const data = JSON.stringify(JSONData, null, 4);
        const blob = new Blob([data], { type: 'application/json;charset=utf-8' });
        const title = HJSchemaJsonStore.value?.config?.title || '我的简历';
        FileSaver.saveAs(blob, `${title}.json`);
        ElMessage.success('JSON 配置文件导出成功！');
        return;
      }
    } catch (e) {
      console.error('LegoJsonStore export failed:', e);
    }

    try {
      const { resumeJsonNewStore } = storeToRefs(appStore.useResumeJsonNewStore);
      if (resumeJsonNewStore?.value) {
        const JSONData = cloneDeep(resumeJsonNewStore.value);
        const data = JSON.stringify(JSONData, null, 4);
        const blob = new Blob([data], { type: 'application/json;charset=utf-8' });
        const title = resumeJsonNewStore.value?.TITLE || '我的简历';
        FileSaver.saveAs(blob, `${title}.json`);
        ElMessage.success('JSON 配置文件导出成功！');
        return;
      }
    } catch (e) {
      console.error('resumeJsonNewStore export failed:', e);
    }

    ElMessage.error('导出 JSON 失败');
  };

  const handleExport = async (type: 'pdf-hd' | 'pdf-print' | 'png' | 'json') => {
    emit('downloadFile', type);
    const fileName = getFileName();

    if (type === 'json') {
      exportJsonConfig();
      handleClose();
      return;
    }

    if (type === 'pdf-print') {
      try {
        exportResumePrint();
        handleClose();
      } catch (err: any) {
        ElMessage.error(err?.message || '打印唤起失败');
      }
      return;
    }

    isExporting.value = true;
    progressPercent.value = 5;
    statusText.value = '正在准备渲染组件...';

    const onProgress = (percent: number, text: string) => {
      progressPercent.value = percent;
      statusText.value = text;
    };

    try {
      if (type === 'pdf-hd') {
        await exportResumePdf({
          fileName,
          scale: 2,
          onProgress
        });
      } else if (type === 'png') {
        await exportResumePNG({
          fileName,
          scale: 2,
          onProgress
        });
      }

      setTimeout(() => {
        isExporting.value = false;
        handleClose();
      }, 800);
    } catch (err: any) {
      console.error('导出失败:', err);
      ElMessage.error(err?.message || '导出失败，请重试');
      isExporting.value = false;
    }
  };

  const handleClose = () => {
    if (isExporting.value) return;
    emit('closeDownloadDialog');
  };
</script>

