<template>
  <el-dialog
    :model-value="dialogVisible"
    width="650px"
    title="导入积木 JSON 数据"
    append-to-body
    destroy-on-close
    class="lego-import-dialog"
    @close="handleClose"
  >
    <div class="dialog-body">
      <div class="tip-banner">
        <svg-icon icon-name="icon-xianshi_jinggao" color="#eab308" size="16px"></svg-icon>
        <span>支持导入积木 JSON 配置文件或普通简历模板 JSON，系统将自动智能解析并自动分页排版呈现。</span>
      </div>

      <!-- 操作工具栏 -->
      <div class="tools-bar">
        <el-upload
          action="#"
          :auto-upload="false"
          :show-file-list="false"
          accept=".json"
          :on-change="handleFileChange"
        >
          <el-button type="primary" plain size="small">
            <svg-icon icon-name="icon-xiazai" color="#10b981" size="14px"></svg-icon>
            上传 JSON 文件
          </el-button>
        </el-upload>
        <el-button size="small" plain @click="loadSampleJson">
          加载示例 JSON
        </el-button>
        <el-button size="small" plain type="info" @click="clearCode">
          清空
        </el-button>
      </div>

      <!-- 导入到模式选择 -->
      <div class="target-bar">
        <span class="target-label">导入到：</span>
        <el-radio-group v-model="importTarget" size="small">
          <el-radio-button label="overwrite">🔴 覆盖当前画布</el-radio-button>
          <el-radio-button label="append">🟢 追加到当前画布</el-radio-button>
        </el-radio-group>
      </div>

      <!-- JSON 代码编辑框 -->
      <div class="editor-wrapper">
        <el-input
          v-model="jsonContent"
          type="textarea"
          :rows="14"
          placeholder="请粘贴 JSON 配置字符串..."
        />
      </div>
    </div>

    <template #footer>
      <div class="dialog-footer">
        <el-button @click="handleClose">取消</el-button>
        <el-button type="primary" :loading="isImporting" @click="confirmImport">
          确认导入并搭建组件
        </el-button>
      </div>
    </template>
  </el-dialog>
</template>

<script lang="ts" setup>
  import { ref } from 'vue';
  import { ElMessage } from 'element-plus';
  import appStore from '@/store';
  import { storeToRefs } from 'pinia';
  import { cloneDeep } from 'lodash';
  import { getUuid } from '@/utils/common';

  const props = defineProps<{
    dialogVisible: boolean;
  }>();

  const emit = defineEmits(['close', 'importSuccess']);

  const jsonContent = ref<string>('');
  const isImporting = ref<boolean>(false);
  const importTarget = ref<'overwrite' | 'append'>('overwrite');

  const { HJSchemaJsonStore } = storeToRefs(appStore.useLegoJsonStore);
  const { changeHJSchemaJsonData } = appStore.useLegoJsonStore;
  const { setUuid } = appStore.useUuidStore;
  const { resetSelectWidget } = appStore.useLegoSelectWidgetStore;

  const handleClose = () => {
    emit('close');
  };

  const clearCode = () => {
    jsonContent.value = '';
  };

  // 读取上传的 JSON 文件
  const handleFileChange = (file: any) => {
    const reader = new FileReader();
    reader.onload = (e: any) => {
      jsonContent.value = e.target.result;
      ElMessage.success('JSON 文件读取成功');
    };
    reader.readAsText(file.raw);
  };

  // 加载示例 JSON 数据
  const loadSampleJson = async () => {
    try {
      const res = await fetch('/static/templates.json');
      if (res.ok) {
        const list = await res.json();
        if (list && list.length > 0) {
          const sample = list[0].template_json || list[0].lego_json || list[0];
          jsonContent.value = JSON.stringify(sample, null, 2);
          ElMessage.success('示例 JSON 加载成功');
          return;
        }
      }
    } catch (err) {
      console.warn('获取本地示例失败', err);
    }
    ElMessage.info('暂未发现本地示例');
  };

  // 保证每一个 Lego Widget 的 CSS 与数据结构 100% 完整无缺，防止 Vue 渲染报错
  const ensureValidLegoWidget = (w: any, overrideTop?: number): any => {
    const css = w.css || {};
    const padding = css.padding || {};
    const safePadding = {
      top: typeof padding === 'object' && padding.top !== undefined ? Number(padding.top) : 0,
      right: typeof padding === 'object' && padding.right !== undefined ? Number(padding.right) : 0,
      bottom: typeof padding === 'object' && padding.bottom !== undefined ? Number(padding.bottom) : 0,
      left: typeof padding === 'object' && padding.left !== undefined ? Number(padding.left) : 0
    };

    const targetTop = overrideTop !== undefined
      ? overrideTop
      : (typeof css.top === 'number' ? css.top : (parseInt(css.top) || 40));

    const safeCss = {
      left: typeof css.left === 'number' ? css.left : (parseInt(css.left) || 40),
      top: targetTop,
      zIndex: typeof css.zIndex === 'number' ? css.zIndex : 1,
      width: typeof css.width === 'number' ? css.width : (parseInt(css.width) || 200),
      height: typeof css.height === 'number' ? css.height : (parseInt(css.height) || 40),
      rotate: typeof css.rotate === 'number' ? css.rotate : 0,
      fontSize: typeof css.fontSize === 'number' ? css.fontSize : 14,
      letterSpace: typeof css.letterSpace === 'number' ? css.letterSpace : (typeof css.letterSpacing === 'number' ? css.letterSpacing : 0),
      lineHeight: css.lineHeight || 1.5,
      fontFamily: css.fontFamily || '微软雅黑',
      fontWeight: css.fontWeight || 400,
      textAlign: css.textAlign || 'left',
      fontColor: css.fontColor || css.color || '#333333',
      backgroundColor: css.backgroundColor || '',
      padding: safePadding,
      borderWidth: typeof css.borderWidth === 'number' ? css.borderWidth : 0,
      borderRadius: typeof css.borderRadius === 'number' ? css.borderRadius : 0,
      borderColor: css.borderColor || '#eee',
      borderStyle: css.borderStyle || 'solid'
    };

    const componentName = w.componentName && w.componentName.startsWith('hj-') ? w.componentName : 'hj-text-1';

    const dataSource = w.dataSource || {};
    if (componentName.startsWith('hj-avatar')) {
      dataSource.avatarSrc = dataSource.avatarSrc || dataSource.avatar || dataSource.url || '';
    }
    if (componentName.startsWith('hj-text')) {
      dataSource.text = dataSource.text !== undefined ? String(dataSource.text) : (w.title || '');
    }

    return {
      id: w.id || getUuid(),
      componentName: componentName,
      commentType: w.commentType || 'text',
      category: w.category || 'text',
      icon: w.icon || '',
      title: w.title || '组件',
      description: w.description || '',
      props: w.props || {},
      customProps: w.customProps || {},
      css: safeCss,
      dataSource: dataSource
    };
  };

  // 将标准简历模块转换为积木 Lego 组件列表 (相对坐标)
  const convertResumeModuleToLegoWidgets = (moduleItem: any): any[] => {
    const widgets: any[] = [];
    const left = 40;
    const contentWidth = 740;

    // 1. 模块标题
    if (moduleItem.title) {
      widgets.push({
        id: getUuid(),
        componentName: 'hj-text-2',
        commentType: 'text',
        icon: '',
        title: moduleItem.title,
        category: 'text',
        props: {},
        css: {
          left: left,
          zIndex: 1,
          width: contentWidth,
          height: 36,
          rotate: 0,
          fontSize: 18,
          letterSpace: 1,
          lineHeight: 1.5,
          fontFamily: '微软雅黑',
          fontWeight: 700,
          textAlign: 'left',
          fontColor: '#10b981',
          padding: { top: 4, right: 8, bottom: 4, left: 8 },
          borderWidth: 0,
          borderRadius: 4,
          borderColor: '#eee',
          borderStyle: 'solid'
        },
        dataSource: {
          text: `▍ ${moduleItem.title}`
        }
      });
    }

    // 2. 针对 BaseInfo (个人资料) 模块特化处理
    if (moduleItem.category === 'base_info' || moduleItem.componentName?.includes('BaseInfo')) {
      const ds = moduleItem.dataSource || {};

      // 头像
      if (ds.avatar && ds.avatar.value) {
        widgets.push({
          id: getUuid(),
          componentName: 'hj-avatar-1',
          commentType: 'avatar',
          icon: '',
          title: '头像',
          category: 'avatar',
          props: {},
          isAvatar: true,
          css: {
            left: 640,
            zIndex: 2,
            width: 120,
            height: 150,
            rotate: 0,
            borderRadius: 8,
            borderWidth: 1,
            borderColor: '#e2e8f0',
            borderStyle: 'solid'
          },
          dataSource: {
            avatarSrc: ds.avatar.value
          }
        });
      }

      // 姓名
      if (ds.name && ds.name.value) {
        widgets.push({
          id: getUuid(),
          componentName: 'hj-text-1',
          commentType: 'text',
          category: 'text',
          props: {},
          css: {
            left: left,
            zIndex: 1,
            width: 580,
            height: 40,
            rotate: 0,
            fontSize: 26,
            letterSpace: 1,
            lineHeight: 1.2,
            fontFamily: '微软雅黑',
            fontWeight: 700,
            textAlign: 'left',
            fontColor: '#1e293b',
            padding: { top: 0, right: 0, bottom: 0, left: 0 },
            borderWidth: 0,
            borderRadius: 0,
            borderColor: '#eee',
            borderStyle: 'solid'
          },
          dataSource: {
            text: ds.name.value
          }
        });
      }

      // 简介
      if (ds.abstract && ds.abstract.value) {
        const cleanAbstract = String(ds.abstract.value).replace(/<[^>]+>/g, '').trim();
        if (cleanAbstract) {
          widgets.push({
            id: getUuid(),
            componentName: 'hj-text-1',
            commentType: 'text',
            category: 'text',
            props: {},
            css: {
              left: left,
              zIndex: 1,
              width: 580,
              height: 30,
              rotate: 0,
              fontSize: 14,
              letterSpace: 0,
              lineHeight: 1.5,
              fontFamily: '微软雅黑',
              fontWeight: 400,
              textAlign: 'left',
              fontColor: '#64748b',
              padding: { top: 0, right: 0, bottom: 0, left: 0 },
              borderWidth: 0,
              borderRadius: 0,
              borderColor: '#eee',
              borderStyle: 'solid'
            },
            dataSource: {
              text: cleanAbstract
            }
          });
        }
      }

      // 基础联系属性
      const infoItems: string[] = [];
      if (ds.age && ds.age.value) infoItems.push(`年龄: ${ds.age.value}岁`);
      if (ds.address && ds.address.value) infoItems.push(`城市: ${ds.address.value}`);
      if (ds.phoneNumber && ds.phoneNumber.value) infoItems.push(`电话: ${ds.phoneNumber.value}`);
      if (ds.email && ds.email.value) infoItems.push(`邮箱: ${ds.email.value}`);
      if (ds.degree && ds.degree.value) infoItems.push(`学历: ${ds.degree.value}`);

      if (infoItems.length > 0) {
        widgets.push({
          id: getUuid(),
          componentName: 'hj-text-1',
          commentType: 'text',
          category: 'text',
          props: {},
          css: {
            left: left,
            zIndex: 1,
            width: 580,
            height: 30,
            rotate: 0,
            fontSize: 13,
            letterSpace: 0,
            lineHeight: 1.5,
            fontFamily: '微软雅黑',
            fontWeight: 400,
            textAlign: 'left',
            fontColor: '#475569',
            padding: { top: 0, right: 0, bottom: 0, left: 0 },
            borderWidth: 0,
            borderRadius: 0,
            borderColor: '#eee',
            borderStyle: 'solid'
          },
          dataSource: {
            text: infoItems.join(' | ')
          }
        });
      }
      return widgets;
    }

    // 3. 通用列表型 / 复杂数据
    const ds = moduleItem.dataSource || {};
    
    // 处理 list 列表
    if (ds.list && Array.isArray(ds.list.value)) {
      ds.list.value.forEach((subItem: any) => {
        const mainTitleParts: string[] = [];
        if (subItem.schoolName && subItem.schoolName.value) mainTitleParts.push(subItem.schoolName.value);
        if (subItem.companyName && subItem.companyName.value) mainTitleParts.push(subItem.companyName.value);
        if (subItem.specialized && subItem.specialized.value) mainTitleParts.push(subItem.specialized.value);
        if (subItem.posts && subItem.posts.value) mainTitleParts.push(subItem.posts.value);
        if (subItem.campusBriefly && subItem.campusBriefly.value) mainTitleParts.push(subItem.campusBriefly.value);
        if (subItem.campusDuty && subItem.campusDuty.value) mainTitleParts.push(`(${subItem.campusDuty.value})`);

        let dateStr = '';
        if (subItem.date && Array.isArray(subItem.date.value)) {
          dateStr = subItem.date.value.join(' ~ ');
        }

        if (mainTitleParts.length > 0 || dateStr) {
          const titleLine = mainTitleParts.join(' - ');
          widgets.push({
            id: getUuid(),
            componentName: 'hj-text-1',
            commentType: 'text',
            category: 'text',
            props: {},
            css: {
              left: left,
              zIndex: 1,
              width: contentWidth,
              height: 28,
              rotate: 0,
              fontSize: 15,
              letterSpace: 0,
              lineHeight: 1.5,
              fontFamily: '微软雅黑',
              fontWeight: 600,
              textAlign: 'left',
              fontColor: '#1e293b',
              padding: { top: 0, right: 0, bottom: 0, left: 0 },
              borderWidth: 0,
              borderRadius: 0,
              borderColor: '#eee',
              borderStyle: 'solid'
            },
            dataSource: {
              text: dateStr ? `${titleLine}  [ ${dateStr} ]` : titleLine
            }
          });
        }

        // 详细描述
        const detailsText: string[] = [];
        if (subItem.majorCourse && subItem.majorCourse.value) detailsText.push(subItem.majorCourse.value);
        if (subItem.campusContent && subItem.campusContent.value) detailsText.push(subItem.campusContent.value);
        if (subItem.introduce && subItem.introduce.value) detailsText.push(subItem.introduce.value);

        if (subItem.jobContent && Array.isArray(subItem.jobContent.value)) {
          subItem.jobContent.value.forEach((jc: any) => {
            if (jc.content && jc.content.value) {
              detailsText.push(jc.content.value);
            }
          });
        }

        detailsText.forEach((rawText) => {
          const cleanText = String(rawText)
            .replace(/<p[^>]*>/gi, '')
            .replace(/<\/p>/gi, '\n')
            .replace(/<li[^>]*>/gi, '• ')
            .replace(/<\/li>/gi, '\n')
            .replace(/<[^>]+>/g, '')
            .trim();

          if (cleanText) {
            const lines = cleanText.split('\n').filter((l: string) => l.trim().length > 0);
            lines.forEach((line: string) => {
              widgets.push({
                id: getUuid(),
                componentName: 'hj-text-1',
                commentType: 'text',
                category: 'text',
                props: {},
                css: {
                  left: left + 10,
                  zIndex: 1,
                  width: contentWidth - 10,
                  height: 24,
                  rotate: 0,
                  fontSize: 13,
                  letterSpace: 0,
                  lineHeight: 1.5,
                  fontFamily: '微软雅黑',
                  fontWeight: 400,
                  textAlign: 'left',
                  fontColor: '#475569',
                  padding: { top: 0, right: 0, bottom: 0, left: 0 },
                  borderWidth: 0,
                  borderRadius: 0,
                  borderColor: '#eee',
                  borderStyle: 'solid'
                },
                dataSource: {
                  text: line.trim()
                }
              });
            });
          }
        });
      });
    } else {
      // 基础对象 key-value 列表
      const kvPairs: string[] = [];
      Object.keys(ds).forEach((key) => {
        const field = ds[key];
        if (field && field.label && field.value) {
          const valStr = typeof field.value === 'string'
            ? field.value.replace(/<[^>]+>/g, '').trim()
            : String(field.value);
          if (valStr) {
            kvPairs.push(`${field.label}: ${valStr}`);
          }
        }
      });

      if (kvPairs.length > 0) {
        kvPairs.forEach((kv) => {
          widgets.push({
            id: getUuid(),
            componentName: 'hj-text-1',
            commentType: 'text',
            category: 'text',
            props: {},
            css: {
              left: left,
              zIndex: 1,
              width: contentWidth,
              height: 28,
              rotate: 0,
              fontSize: 13,
              letterSpace: 0,
              lineHeight: 1.5,
              fontFamily: '微软雅黑',
              fontWeight: 400,
              textAlign: 'left',
              fontColor: '#475569',
              padding: { top: 0, right: 0, bottom: 0, left: 0 },
              borderWidth: 0,
              borderRadius: 0,
              borderColor: '#eee',
              borderStyle: 'solid'
            },
            dataSource: {
              text: kv
            }
          });
        });
      }
    }

    return widgets;
  };

  // 标准化与规范化 JSON schema 格式 (支持精准自动分页与布局)
  const normalizeLegoSchema = (rawJson: any): any => {
    let legoData = cloneDeep(rawJson);

    // 1. 如果有包裹字段
    if (legoData.template_json) legoData = legoData.template_json;
    if (legoData.lego_json) legoData = legoData.lego_json;

    // 2. 检查 componentsTree
    if (!legoData.componentsTree || !Array.isArray(legoData.componentsTree)) {
      throw new Error('JSON 格式不包含 componentsTree 数组');
    }

    // 3. 判断 componentsTree 内部是否已包含 page 节点 (严格判断)
    const hasPages = legoData.componentsTree.some((item: any) =>
      item && (item.componentName === 'page' || item.commentType === 'page')
    );

    if (hasPages) {
      legoData.componentsTree = legoData.componentsTree.map((pageItem: any) => {
        const children = (pageItem.children || []).map((w: any) => ensureValidLegoWidget(w));
        return {
          id: pageItem.id || getUuid(),
          componentName: 'page',
          commentType: 'page',
          oldPageIndex: pageItem.oldPageIndex || '',
          children: children
        };
      });
      // 强制格式化容器尺寸为数值
      legoData.css = legoData.css || {};
      legoData.css.width = typeof legoData.css.width === 'number' ? legoData.css.width : (parseInt(legoData.css.width) || 820);
      legoData.css.height = typeof legoData.css.height === 'number' ? legoData.css.height : (parseInt(legoData.css.height) || 1160);
      return legoData;
    }

    // 4. 非原生 Page 格式：自动智能垂直排版 & 自动分页
    const MAX_PAGE_TOP = 1000; // 单页最大可用高度 (A4高度 1160)
    const pages: any[] = [
      {
        id: getUuid(),
        componentName: 'page',
        commentType: 'page',
        oldPageIndex: '',
        children: []
      }
    ];

    let currentPageIdx = 0;
    let currentTop = 40;
    let baseInfoTopStart = 40;

    const pushWidgetToAutoPage = (widgetRaw: any) => {
      const h = widgetRaw.css?.height || 30;

      // 如果当前页高度不足，且当前页已有组件，自动创建新一页
      if (currentTop + h > MAX_PAGE_TOP && pages[currentPageIdx].children.length > 0) {
        currentPageIdx++;
        currentTop = 40;
        baseInfoTopStart = 40;
        pages.push({
          id: getUuid(),
          componentName: 'page',
          commentType: 'page',
          oldPageIndex: '',
          children: []
        });
      }

      let targetTop = currentTop;
      if (widgetRaw.isAvatar) {
        targetTop = baseInfoTopStart;
      } else {
        currentTop += h + 8;
      }

      const validWidget = ensureValidLegoWidget(widgetRaw, targetTop);
      pages[currentPageIdx].children.push(validWidget);
    };

    legoData.componentsTree.forEach((item: any) => {
      if (item.componentName && item.componentName.startsWith('hj-')) {
        pushWidgetToAutoPage(item);
      } else {
        baseInfoTopStart = currentTop;
        const widgets = convertResumeModuleToLegoWidgets(item);
        widgets.forEach((w) => {
          pushWidgetToAutoPage(w);
        });
        currentTop += 15; // 模块间留空白间隙
      }
    });

    const resultSchema: any = {
      id: legoData.id || getUuid(),
      version: legoData.version || '1.0.0',
      componentsTree: pages,
      i18n: legoData.i18n || {},
      constants: legoData.constants || {},
      css: {
        width: 820,
        height: 1160,
        background: '#ffffff',
        opacity: 1,
        backgroundImage: '',
        fontFamily: '微软雅黑',
        themeColor: '#10b981'
      },
      config: legoData.config || { title: legoData.title || '导入的简历制作' },
      meta: legoData.meta || {},
      dataSource: legoData.dataSource || {}
    };

    return resultSchema;
  };

  // 确认导入并渲染到画布
  const confirmImport = async () => {
    if (!jsonContent.value.trim()) {
      ElMessage.warning('请输入或上传 JSON 数据！');
      return;
    }

    try {
      isImporting.value = true;
      const parsedData = JSON.parse(jsonContent.value);

      // 智能转化与自动分页排版
      const normalizedData = normalizeLegoSchema(parsedData);

      console.log('自动分页后的 Lego Schema:', normalizedData);

      if (importTarget.value === 'overwrite') {
        changeHJSchemaJsonData(normalizedData);
        resetSelectWidget();
        setUuid(); // 重新渲染画板
        ElMessage.success('🎉 导入成功！已覆盖当前画布数据。');
      } else {
        // 追加模式
        const newPages = normalizedData.componentsTree.map((page: any) => ({
          ...page,
          id: getUuid(),
          children: (page.children || []).map((w: any) => ensureValidLegoWidget(w))
        }));

        if (!HJSchemaJsonStore.value.componentsTree) {
          HJSchemaJsonStore.value.componentsTree = [];
        }

        HJSchemaJsonStore.value.componentsTree.push(...newPages);
        resetSelectWidget();
        setUuid();
        ElMessage.success('🎉 导入成功！已将新页面追加到当前画布尾部。');
      }

      emit('importSuccess');
      handleClose();
    } catch (e: any) {
      console.error('导入解析错误:', e);
      ElMessage.error(e.message || 'JSON 解析失败，请检查 JSON 字符串语法格式！');
    } finally {
      isImporting.value = false;
    }
  };
</script>

<style lang="scss" scoped>
  .lego-import-dialog {
    .dialog-body {
      padding: 0 10px;
      .tip-banner {
        display: flex;
        align-items: center;
        gap: 8px;
        background-color: #fefce8;
        border: 1px solid #fef08a;
        padding: 10px 14px;
        border-radius: 6px;
        margin-bottom: 14px;
        font-size: 13px;
        color: #854d0e;
      }

      .tools-bar {
        display: flex;
        align-items: center;
        gap: 12px;
        margin-bottom: 10px;
      }

      .target-bar {
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 12px;
        background-color: #f8fafc;
        padding: 8px 12px;
        border-radius: 6px;
        border: 1px solid #e2e8f0;

        .target-label {
          font-size: 13px;
          font-weight: 600;
          color: #475569;
        }
